{"sql": "-- Helper function to get current user ID from session context
CREATE OR REPLACE FUNCTION public.current_user_id() 
RETURNS UUID AS $$
BEGIN
    RETURN COALESCE(current_setting('app.current_user_id', true)::UUID, NULL);
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;"}

{"sql": "-- Helper function to check if user is channel owner
CREATE OR REPLACE FUNCTION public.is_channel_owner(p_channel_id UUID, p_user_id UUID) 
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 
        FROM public.channels 
        WHERE id = p_channel_id 
        AND owner_id = p_user_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;"}

{"sql": "-- Helper function to check if user is channel moderator
CREATE OR REPLACE FUNCTION public.is_channel_moderator(p_channel_id UUID, p_user_id UUID) 
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 
        FROM public.channel_moderators 
        WHERE channel_id = p_channel_id 
        AND user_id = p_user_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;"}

{"sql": "-- Helper function to check if user can moderate channel (owner OR moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(p_channel_id UUID, p_user_id UUID) 
RETURNS BOOLEAN AS $$
BEGIN
    RETURN public.is_channel_owner(p_channel_id, p_user_id) 
        OR public.is_channel_moderator(p_channel_id, p_user_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;"}

{"sql": "-- Enable RLS on all tables
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;"}

{"sql": "-- Channel Moderators table policies

-- SELECT: Users can see moderator lists for channels they can access
CREATE POLICY "channel_moderators_select_accessible" ON public.channel_moderators
    FOR SELECT
    USING (
        public.can_access_channel(channel_id, public.current_user_id())
    );

-- INSERT: Only channel owners can add moderators
CREATE POLICY "channel_moderators_insert_owner" ON public.channel_moderators
    FOR INSERT
    TO authenticated
    WITH CHECK (
        public.is_channel_owner(channel_id, public.current_user_id())
        AND public.current_user_id() IS NOT NULL
    );

-- DELETE: Channel owners can remove moderators; moderators can remove themselves
CREATE POLICY "channel_moderators_delete_owner_or_self" ON public.channel_moderators
    FOR DELETE
    USING (
        public.is_channel_owner(channel_id, public.current_user_id())
        OR user_id = public.current_user_id()
    );

-- No UPDATE policy needed as this is a junction table with no updatable fields"}

{"sql": "-- Additional indexes to optimize RLS policy performance

-- Optimize channel access checks
CREATE INDEX IF NOT EXISTS idx_channels_owner_public ON public.channels (owner_id, is_public);

-- Optimize moderator lookups
CREATE INDEX IF NOT EXISTS idx_channel_moderators_lookup ON public.channel_moderators (channel_id, user_id);

-- Optimize post-channel relationships for RLS
CREATE INDEX IF NOT EXISTS idx_posts_channel_author ON public.posts (channel_id, author_id);

-- Optimize comment-post relationships for RLS
CREATE INDEX IF NOT EXISTS idx_comments_post_author ON public.comments (post_id, author_id);"}

{"sql": "-- Create authenticated role if it doesn't exist
DO $$ 
BEGIN
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
        CREATE ROLE authenticated;
    END IF;
END
$$;"}

{"sql": "-- Grant necessary permissions to authenticated role
GRANT USAGE ON SCHEMA public TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.users TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.channels TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.posts TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.comments TO authenticated;
GRANT SELECT, INSERT, DELETE ON public.channel_moderators TO authenticated;

-- Grant execute permissions on helper functions
GRANT EXECUTE ON FUNCTION public.current_user_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_channel_owner(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_channel_moderator(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.can_moderate_channel(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.can_access_channel(UUID, UUID) TO authenticated;"}

{"sql": "-- Create a comprehensive test function to demonstrate RLS functionality
CREATE OR REPLACE FUNCTION public.test_rls_system()
RETURNS TEXT AS $$
DECLARE
    test_results TEXT := '';
    user1_id UUID;
    user2_id UUID;
    user3_id UUID;
    channel1_id UUID;
    channel2_id UUID;
    post1_id UUID;
    comment1_id UUID;
    visible_count INTEGER;
BEGIN
    -- Create test users
    INSERT INTO public.users (username, email, is_public) VALUES 
        ('user1', 'user1@test.com', true),
        ('user2', 'user2@test.com', true),
        ('user3', 'user3@test.com', false)
    RETURNING id INTO user1_id;

    SELECT id INTO user2_id FROM public.users WHERE username = 'user2';
    SELECT id INTO user3_id FROM public.users WHERE username = 'user3';

    test_results := test_results || 'Created test users' || E'\n';

    -- Create test channels
    INSERT INTO public.channels (name, description, is_public, owner_id) VALUES 
        ('Public Channel', 'A public channel', true, user1_id),
        ('Private Channel', 'A private channel', false, user1_id)
    RETURNING id INTO channel1_id;

    SELECT id INTO channel2_id FROM public.channels WHERE name = 'Private Channel';

    test_results := test_results || 'Created test channels' || E'\n';

    -- Add user2 as moderator of channel1
    INSERT INTO public.channel_moderators (channel_id, user_id) VALUES (channel1_id, user2_id);

    test_results := test_results || 'Added moderator to channel' || E'\n';

    -- Create test posts
    INSERT INTO public.posts (channel_id, author_id, title, content) VALUES 
        (channel1_id, user1_id, 'Test Post 1', 'This is a test post'),
        (channel2_id, user1_id, 'Private Post', 'This is a private post')
    RETURNING id INTO post1_id;

    test_results := test_results || 'Created test posts' || E'\n';

    -- Create test comments
    INSERT INTO public.comments (post_id, author_id, content) VALUES 
        (post1_id, user2_id, 'This is a test comment')
    RETURNING id INTO comment1_id;

    test_results := test_results || 'Created test comments' || E'\n';

    -- Test RLS by simulating different user sessions

    -- Test 1: user3 should only see public channels
    PERFORM set_config('app.current_user_id', user3_id::text, true);
    SELECT COUNT(*) INTO visible_count FROM public.channels;
    test_results := test_results || 'User3 can see ' || visible_count || ' channels (should be 1 public)' || E'\n';

    -- Test 2: user2 should see both channels (moderator of channel1, and public channel2)
    PERFORM set_config('app.current_user_id', user2_id::text, true);
    SELECT COUNT(*) INTO visible_count FROM public.channels;
    test_results := test_results || 'User2 can see ' || visible_count || ' channels (should be 2)' || E'\n';

    -- Test 3: user1 should see both channels (owner)
    PERFORM set_config('app.current_user_id', user1_id::text, true);
    SELECT COUNT(*) INTO visible_count FROM public.channels;
    test_results := test_results || 'User1 can see ' || visible_count || ' channels (should be 2)' || E'\n';

    -- Test 4: user3 should only see posts in public channels
    PERFORM set_config('app.current_user_id', user3_id::text, true);
    SELECT COUNT(*) INTO visible_count FROM public.posts;
    test_results := test_results || 'User3 can see ' || visible_count || ' posts (should be 1 from public channel)' || E'\n';

    -- Clean up test data
    DELETE FROM public.comments WHERE id = comment1_id;
    DELETE FROM public.posts WHERE author_id IN (user1_id, user2_id, user3_id);
    DELETE FROM public.channel_moderators WHERE user_id IN (user1_id, user2_id, user3_id);
    DELETE FROM public.channels WHERE owner_id IN (user1_id, user2_id, user3_id);
    DELETE FROM public.users WHERE id IN (user1_id, user2_id, user3_id);

    test_results := test_results || 'Cleaned up test data' || E'\n';
    test_results := test_results || 'RLS system test completed successfully!' || E'\n';

    RETURN test_results;
END;
$$ LANGUAGE plpgsql;"}
